// Golden values of the project engineering register (docs/spec/09 §7–8, 00 §8.8): the Synthesis (KPI tiles, "Who is
// waiting for what" matrix, discipline cards, gate, recent changes), the four discipline screens (header, KPI tiles,
// inputs, deliverables, outputs, consistency checks and their chips), the import wizard and the sidebar badges against
// the prototype's own render values (src/features/eng/eng.golden.json, generated by scripts/proto-golden-eng.ts — the
// prototype logic run in node:vm, English). The prototype's register (ENG_* constants, HLT-026) is rebuilt as stored
// records; the sequence the generator played with the prototype's handlers is replayed here step by step with the
// domain rules (`planImport`, the check notes, the deliverable steps). Deliberate deviations are asserted explicitly.
import { describe, expect, it } from 'vitest';
import { PROTO } from '@/server/prototype';
import { checkStatus, documentStatus, isoOfDisplayDate, outputState, type CheckSeverity, type Discipline, type DocRecipient } from '@/server/db/codes';
import GOLD from '@/features/eng/eng.golden.json';
import {
  CHECK_NOTE, DELIVERABLE_STEP, DISCIPLINE_SEGMENT, IMPORT_ROWS, canValidateRelease, checkFilterOf, deriveRegister, disciplineOfSegment, disciplineView, engBadges,
  blockingCounts, generatedText, importTargetFor, importTargetOf, importWizardView, inputLatest, inputStateOf, outputStateOf, planImport, prevRev,
  primaryImportTarget, shortDoc, synthesisView, type CheckFilter, type EngRaw, type EngRegister, type EngScreen,
} from './engineering';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = (GOLD as any).en;
const HLT = 'HLT-026';
const DISCS: Discipline[] = ['process', 'meca', 'elec', 'auto'];

/** The prototype's register as stored records (ENG_DISC, ENG_INPUTS, ENG_DOCS, ENG_CHECKS, ENG_OUTPUTS, ENG_CHANGES, ENG_TOOLS, ENG_MAP, ENG_DELTAS). */
function protoRaw(): EngRaw {
  const rules = PROTO.ENG_RULES as Record<string, string>;
  return {
    projectCode: HLT,
    disciplines: Object.entries(PROTO.ENG_DISC as Record<string, [string, string, string, string]>).map(([code, [, icon, lead, tools]]) => ({ code: code as Discipline, icon, lead, tools })),
    inputs: (PROTO.ENG_INPUTS as any[]).map((i) => ({
      consumer: i.disc, documentNumber: i.doc, revisionInUse: i.rev, acknowledged: i.ack, providerParty: i.from || null, externalTitle: i.title || null,
    })),
    docs: (PROTO.ENG_DOCS as any[]).map((d) => ({
      number: d.id, title: d.title, discipline: d.disc, revision: d.rev, status: documentStatus.code(d.status), issuedOn: isoOfDisplayDate(d.date)!, author: d.by, recipients: d.to,
    })),
    checks: (PROTO.ENG_CHECKS as any[]).map((c) => ({
      number: c.id, rulePair: c.pair, ruleLabel: rules[c.pair], severity: c.sev as CheckSeverity, title: c.title, detail: c.detail, owner: c.disc, status: checkStatus.code(c.status), note: '',
    })),
    outputs: (PROTO.ENG_OUTPUTS as any[]).map((o) => ({
      number: o.id, discipline: o.disc, name: o.name, recipients: o.to, source: o.source, state: outputState.code(o.state), generatedAt: null, generatedFormat: null,
    })),
    changes: (PROTO.ENG_CHANGES as [string, string, string][]).map(([date, text, rcp]) => ({ changedOn: isoOfDisplayDate(date)!, text, recipients: rcp.split(',') as DocRecipient[] })),
    tools: (PROTO.ENG_TOOLS as [string, Discipline][]).map(([label, discipline], position) => ({ position, label, discipline })),
    mappings: (PROTO.ENG_MAP as [string, string][]).map(([sourceColumn, targetField]) => ({ sourceColumn, targetField })),
    deltas: (PROTO.ENG_DELTAS as [string, string][]).map(([sym, label]) => ({ kind: sym === '+' ? ('new' as const) : ('changed' as const), label })),
  };
}

const TODAY = '2026-10-08';
const NOW = '2026-10-08T09:30:00.000Z';
const parisDay = (iso: string) => iso.slice(0, 10);

const checkSet = (raw: EngRaw, number: string, status: 'resolved' | 'sent_back'): EngRaw => ({
  ...raw, checks: raw.checks.map((c) => (c.number === number ? { ...c, status, note: CHECK_NOTE[status] } : c)),
});
const docStep = (raw: EngRaw, number: string, step: keyof typeof DELIVERABLE_STEP): EngRaw => ({
  ...raw,
  docs: raw.docs.map((d) => {
    if (d.number !== number) return d;
    if (d.status !== DELIVERABLE_STEP[step].from) throw new Error(`${number} is not ${DELIVERABLE_STEP[step].from}`);
    return { ...d, status: DELIVERABLE_STEP[step].to };
  }),
});

const confirm = (raw: EngRaw, disc: Discipline, doc: string): EngRaw => ({
  ...raw, inputs: raw.inputs.map((i) => (i.consumer === disc && i.documentNumber === doc ? { ...i, acknowledged: true } : i)),
});
const generate = (raw: EngRaw, number: string): EngRaw => ({
  ...raw, outputs: raw.outputs.map((o) => (o.number === number ? { ...o, generatedAt: NOW, generatedFormat: 'xlsx' } : o)),
});

/** The generator's sequence (`SEQUENCE`), replayed on stored records with the domain rules. */
const SEQUENCE_STEPS: Record<string, (r: EngRaw) => EngRaw> = {
  'confirm meca PID-HLT-026': (r) => confirm(r, 'meca', 'PID-HLT-026'),
  'resolve C-01': (r) => checkSet(r, 'C-01', 'resolved'),
  'send back C-03': (r) => checkSet(r, 'C-03', 'sent_back'),
  'import elec LST-INS-026': (r) => planImport(r, { consumer: 'elec', documentNumber: 'LST-INS-026' }),
  'freeze SCH-ELE-026': (r) => docStep(r, 'SCH-ELE-026', 'freeze'),
  'propose BOM-MEC-026': (r) => docStep(r, 'BOM-MEC-026', 'propose'),
  'validate BOM-MEC-026': (r) => docStep(r, 'BOM-MEC-026', 'validate'),
  'generate O-01': (r) => generate(r, 'O-01'),
  'import auto LST-IO-026': (r) => planImport(r, { consumer: 'auto', documentNumber: 'LST-IO-026' }),
  'resolve C-02': (r) => checkSet(r, 'C-02', 'resolved'),
  'send back C-04': (r) => checkSet(r, 'C-04', 'sent_back'),
  'propose SCH-ELE-026': (r) => docStep(r, 'SCH-ELE-026', 'propose'),
  'validate SCH-ELE-026': (r) => docStep(r, 'SCH-ELE-026', 'validate'),
  'generate O-03': (r) => generate(r, 'O-03'),
  'confirm elec LST-INS-026': (r) => confirm(r, 'elec', 'LST-INS-026'),
  'import process GA-HLT-026': (r) => planImport(r, { consumer: 'process', documentNumber: 'GA-HLT-026' }),
  'propose FDS-HLT-026': (r) => docStep(r, 'FDS-HLT-026', 'propose'),
};

const pickKeys = (o: any, keys: string[]) => Object.fromEntries(keys.map((k) => [k, o[k]]));

/** Synthesis in the generator's shape. */
function synthesisShape(reg: EngRegister) {
  const v = synthesisView(reg);
  return {
    isEngProj: true,
    kpis: v.kpis,
    from: v.from.map((f) => f.label),
    matrix: v.matrix.map((r) => ({ label: r.label, cells: r.cells.map((c) => ({ bg: c.bg, items: c.items.map((i) => pickKeys(i, ['label', 'sub', 'color', 'border', 'dot', 'dotBorder'])) })) })),
    discCards: v.discCards.map((d) => pickKeys(d, ['label', 'icon', 'lead', 'tools', 'pct', 'relText', 'openText', 'openColor'])),
    gate: {
      cls: v.gate.cls,
      text: v.gate.text,
      items: v.gate.items.map((c) => ({ id: c.number, title: c.title, ruleLabel: c.ruleLabel, lead: c.lead, status: c.status, stClass: c.stClass, sevDot: c.sevDot, disc: c.owner })),
    },
    changes: v.changes,
  };
}

const CHIP_COLORS = (on: boolean) =>
  on
    ? { bg: 'var(--color-accent-900)', border: 'var(--color-accent-700)', color: 'var(--color-accent-200)' }
    : { bg: 'transparent', border: 'var(--color-neutral-800)', color: 'var(--color-neutral-300)' };

/** Discipline screen in the generator's shape. */
function disciplineShape(reg: EngRegister, disc: Discipline, filter: CheckFilter = 'all') {
  const v = disciplineView(reg, disc, { filter, todayIso: TODAY, parisDay });
  return {
    head: v.head,
    kpis: v.kpis,
    inputs: v.inputs.map((r) => pickKeys(r, ['doc', 'title', 'from', 'revText', 'latestText', 'revColor', 'state', 'stClass', 'canConfirm', 'canImport'])),
    docs: v.docs,
    outputs: v.outputs.map((o) => ({ ...pickKeys(o, ['id', 'name', 'toText', 'source', 'state', 'stateText', 'stClass', 'canGen']), genText: generatedText(o.generated) })),
    checks: v.checks,
    chips: v.chips.map((c) => ({ label: c.label, count: String(c.count), ...CHIP_COLORS(c.value === v.filter) })),
  };
}

/** Golden discipline values with the keys in our order (genText '' when never generated). */
const goldDiscipline = (g: any) => ({
  ...g,
  outputs: g.outputs.map((o: any) => ({ ...pickKeys(o, ['id', 'name', 'toText', 'source', 'state', 'stateText', 'stClass', 'canGen']), genText: o.genText })),
  filters: undefined,
});
const strip = (x: any) => JSON.parse(JSON.stringify(x));
/** Deliberate deviation from the prototype's English: the singular gate tag. Applied to golden values before comparing. */
const DEVIATIONS: Record<string, string> = { 'Blocked by 1 blocking inconsistencies': 'Blocked by 1 blocking inconsistency' };
const fixGold = (x: any): any => JSON.parse(JSON.stringify(x), (_k, v) => (typeof v === 'string' && Object.hasOwn(DEVIATIONS, v) ? DEVIATIONS[v] : v));

describe('pure rules', () => {
  it('prevRev, shortDoc, input latest / state, output state, deliverable steps, release validation', () => {
    expect(['D', 'B', 'A', '2', 'AA'].map(prevRev)).toEqual(['C', 'A', 'A', '2', 'AA']);
    expect(['PID-HLT-026', 'LST-INS-026', 'BOD-CLI-026', 'GA-HLT-026', 'VAR-PLC-026'].map((d) => shortDoc(d, HLT))).toEqual(['PID', 'LST-INS', 'BOD-CLI', 'GA', 'VAR-PLC']);
    // 09 OQ12: the provider's Frozen rev B reads "latest rev A".
    expect([inputLatest('C', { revision: 'D', status: 'released' }), inputLatest('B', { revision: 'B', status: 'frozen' }), inputLatest('2', null)]).toEqual(['D', 'A', '2']);
    expect([inputStateOf('C', 'D', true), inputStateOf('D', 'D', true), inputStateOf('D', 'D', false)]).toEqual(['outdated', 'up_to_date', 'to_confirm']);
    expect([outputStateOf('blocked', 2), outputStateOf('blocked', 0), outputStateOf('stale', 0), outputStateOf('partial', 3)]).toEqual(['blocked', 'ready', 'stale', 'partial']);
    expect(Object.values(DELIVERABLE_STEP).map((s) => [s.from, s.to, s.label])).toEqual([
      ['draft', 'frozen', 'Freeze'], ['frozen', 'release_proposed', 'Propose release'], ['release_proposed', 'released', 'Validate release (PM)'],
    ]);
    expect([
      canValidateRelease({ role: 'director' }, false), canValidateRelease({ role: 'pm' }, true), canValidateRelease({ role: 'pm' }, false),
      canValidateRelease({ role: 'englead' }, true), canValidateRelease({ role: 'quality' }, false),
    ]).toEqual([true, true, false, false, false]);
    expect([checkFilterOf('open'), checkFilterOf('sent_back'), checkFilterOf('Resolved'), checkFilterOf(undefined)]).toEqual(['open', 'sent_back', 'all', 'all']);
    expect(DISCIPLINES_SEGMENTS()).toEqual([['process', 'process'], ['meca', 'mechanical'], ['elec', 'electrical'], ['auto', 'automation']]);
    expect([disciplineOfSegment('mechanical'), disciplineOfSegment('meca'), disciplineOfSegment(undefined)]).toEqual(['meca', null, null]);
  });

  it('generation stamp: today, an earlier day, never', () => {
    const reg = deriveRegister(generate(protoRaw(), 'O-01'));
    expect(generatedText(disciplineView(reg, 'process', { todayIso: TODAY, parisDay }).outputs[0].generated)).toBe('Generated today · xlsx');
    expect(generatedText(disciplineView(reg, 'process', { todayIso: '2026-10-09', parisDay }).outputs[0].generated)).toBe('Generated 8 Oct · xlsx');
    expect(generatedText(disciplineView(reg, 'meca', { todayIso: TODAY, parisDay }).outputs[0].generated)).toBe('');
  });
});

const DISCIPLINES_SEGMENTS = () => DISCS.map((d) => [d, DISCIPLINE_SEGMENT[d]]);

describe('default state (prototype render values)', () => {
  const reg = deriveRegister(protoRaw());

  it('Synthesis: KPI tiles, matrix, discipline cards, gate, recent changes', () => {
    expect(strip(synthesisShape(reg))).toEqual(G.default.synthesis);
  });

  it.each(DISCS)('%s screen: header, KPIs, inputs, deliverables, outputs, checks, chips', (k) => {
    expect(strip(disciplineShape(reg, k))).toEqual(strip(goldDiscipline(G.default.disciplines[k])));
  });

  it.each(DISCS)('%s screen: check filters Open / Sent back / Resolved', (k) => {
    const f = G.default.disciplines[k].filters;
    expect({
      open: disciplineView(reg, k, { filter: 'open' }).checks.map((c) => c.id),
      'Sent back': disciplineView(reg, k, { filter: 'sent_back' }).checks.map((c) => c.id),
      Resolved: disciplineView(reg, k, { filter: 'resolved' }).checks.map((c) => c.id),
    }).toEqual(f);
  });

  it('sidebar badges', () => {
    expect(engBadges(blockingCounts(reg))).toEqual(G.default.badges);
    // Projects without a register: no badge (the prototype keys the register to HLT-026).
    expect(engBadges(blockingCounts(null))).toEqual(G.otherProject.badges);
    expect(G.otherProject).toMatchObject({ isEngProj: false, engNotProj: true });
  });
});

describe('sequence played with the prototype handlers', () => {
  it('replays every step and matches the Synthesis, the discipline acted on and the badges after each one', () => {
    let raw = protoRaw();
    expect(G.sequence.map((st: any) => st.name)).toEqual(Object.keys(SEQUENCE_STEPS));
    for (const st of G.sequence) {
      raw = SEQUENCE_STEPS[st.name](raw);
      const reg = deriveRegister(raw);
      expect([st.name, strip(synthesisShape(reg))]).toEqual([st.name, fixGold(st.synthesis)]);
      expect([st.name, strip(disciplineShape(reg, st.disc))]).toEqual([st.name, strip(goldDiscipline(st.discipline))]);
      expect([st.name, engBadges(blockingCounts(reg))]).toEqual([st.name, st.badges]);
    }
    // The end of the sequence: no blocking check left, the gate can pass, every output ready but the partial purchasing BOM and the stale index.
    const last = G.sequence.at(-1);
    expect([last.synthesis.gate.text, last.badges.eng, last.synthesis.kpis[3].value]).toEqual(['Ready to pass', '', '4 / 6']);
  });

  it('the Automation import of the instrument list — deviation: listed as an Automation input (the prototype stored it unlisted)', () => {
    const reg = deriveRegister(planImport(protoRaw(), { consumer: 'auto', documentNumber: 'LST-INS-026' }));
    const g = G.importAutoInstrumentList;
    const extra = { doc: 'LST-INS-026', title: 'Instrument list', from: 'Process', revText: 'rev D', latestText: 'rev D', revColor: 'var(--color-text)', state: 'To confirm', stClass: 'tag tag-outline', canConfirm: true, canImport: false };
    const auto = strip(disciplineShape(reg, 'auto'));
    const gAuto = strip(goldDiscipline(g.disciplines.auto));
    expect(auto.inputs).toEqual([...gAuto.inputs, extra]);
    expect(gAuto.kpis[0]).toMatchObject({ value: '2 / 3', sub: '1 to confirm' });
    expect(auto.kpis[0]).toMatchObject({ value: '3 / 4', sub: '2 to confirm' });
    expect({ ...auto, inputs: gAuto.inputs, kpis: gAuto.kpis }).toEqual(gAuto);
    for (const k of ['process', 'meca', 'elec'] as Discipline[]) expect(strip(disciplineShape(reg, k))).toEqual(strip(goldDiscipline(g.disciplines[k])));
    // Synthesis: the same tiles (the new input is up to date with the released rev D) and one more pill Process → Automation.
    const syn = strip(synthesisShape(reg));
    expect(syn.kpis).toEqual(g.synthesis.kpis);
    const autoRow = syn.matrix.find((r: any) => r.label === 'Automation');
    expect(autoRow.cells[1].items.map((i: any) => [i.label, i.sub])).toEqual([['PID', 'rev D'], ['LST-INS', 'rev D']]);
    const gRow = g.synthesis.matrix.find((r: any) => r.label === 'Automation');
    expect(gRow.cells[1].items.map((i: any) => [i.label, i.sub])).toEqual([['PID', 'rev D']]);
    expect({ ...syn, matrix: g.synthesis.matrix }).toEqual(g.synthesis);
  });

  it('gate tag: singular for one blocking inconsistency (the prototype wrote "1 blocking inconsistencies")', () => {
    const one = deriveRegister(['C-01', 'C-02', 'C-03'].reduce((x, n) => checkSet(x, n, 'resolved'), protoRaw()));
    expect(synthesisView(one).gate.text).toBe('Blocked by 1 blocking inconsistency');
    expect(engBadges(blockingCounts(one))).toEqual({ eng: '1', 'eng-process': '', 'eng-meca': '', 'eng-elec': '', 'eng-auto': '1' });
  });

  it('planImport closes only the consumer’s unresolved revision checks (sent back included), with the imported revision', () => {
    const elec = planImport(protoRaw(), { consumer: 'elec', documentNumber: 'LST-INS-026' });
    expect(elec.checks.filter((c) => c.status === 'resolved' && c.note).map((c) => [c.number, c.note])).toEqual([['C-08', 'Closed by import of rev D']]);
    expect(elec.inputs.filter((i) => i.consumer === 'elec' && !i.acknowledged).map((i) => [i.documentNumber, i.revisionInUse])).toEqual([['PID-HLT-026', 'D'], ['LST-INS-026', 'D']]);
    const auto = planImport(protoRaw(), { consumer: 'auto', documentNumber: 'LST-IO-026' });
    expect(auto.checks.find((c) => c.number === 'C-09')).toMatchObject({ status: 'resolved', note: 'Closed by import of rev B' });
    const meca = planImport(protoRaw(), { consumer: 'meca', documentNumber: 'LST-INS-026' });
    expect(meca.checks).toEqual(protoRaw().checks);
    // A revision check sent back to the tool "closes on next import" (the prototype resolved C-08 whatever its status);
    // one already resolved keeps its note.
    const sentBack = planImport(checkSet(protoRaw(), 'C-08', 'sent_back'), { consumer: 'elec', documentNumber: 'LST-INS-026' });
    expect(sentBack.checks.find((c) => c.number === 'C-08')).toMatchObject({ status: 'resolved', note: 'Closed by import of rev D' });
    const resolved = planImport(checkSet(protoRaw(), 'C-09', 'resolved'), { consumer: 'auto', documentNumber: 'LST-IO-026' });
    expect(resolved.checks.find((c) => c.number === 'C-09')).toMatchObject({ status: 'resolved', note: 'Resolved in Keystone' });
    expect(() => planImport(protoRaw(), { consumer: 'meca', documentNumber: 'BOD-CLI-026' })).toThrow(/Unknown document/);
    // A discipline does not import its own deliverable as an input.
    expect(() => planImport(protoRaw(), { consumer: 'elec', documentNumber: 'SCH-ELE-026' })).toThrow(/not an input/);
  });
});

describe('import wizard', () => {
  const reg = deriveRegister(protoRaw());
  const W = G.wizard;
  const shape = (v: ReturnType<typeof importWizardView>, open = true) => ({
    open,
    target: v.target,
    file: v.file,
    steps: v.steps,
    tools: v.tools.map((t) => pickKeys(t, ['label', 'disc', 'bg', 'border', 'dot'])),
    map: v.map,
    stats: v.stats,
    deltas: v.deltas,
    is1: v.is1,
    is2: v.is2,
    is3: v.is3,
    canBack: v.canBack,
    canNext: v.canNext,
  });

  it('header presets of the five screens (5137)', () => {
    for (const screen of ['eng', 'eng-process', 'eng-meca', 'eng-elec', 'eng-auto'] as EngScreen[]) {
      const t = primaryImportTarget(reg, screen)!;
      const st = W.presets[screen].state;
      expect([t.disc, t.doc, t.tool]).toEqual([st.disc, st.doc, st.tool]);
      expect(strip(shape(importWizardView(reg, t, 1)))).toEqual(W.presets[screen].vals);
    }
  });

  it('body "Import a list" per discipline and "Import new rev" on each outdated input (`openImp`)', () => {
    for (const k of DISCS) {
      const t = importTargetFor(reg, k)!;
      const st = W.body[k].state;
      expect([t.disc, t.doc, t.tool]).toEqual([st.disc, st.doc, st.tool]);
      expect(strip(shape(importWizardView(reg, t, 1)))).toEqual(W.body[k].vals);
    }
    const outdated = reg.inputs.filter((i) => i.outdated).map((i) => `${i.consumer}|${i.documentNumber}`);
    expect(outdated).toEqual(Object.keys(W.importNewRev));
    for (const key of outdated) {
      const [disc, doc] = key.split('|') as [Discipline, string];
      const t = importTargetFor(reg, disc, doc)!;
      const st = W.importNewRev[key].state;
      expect([t.disc, t.doc, t.tool]).toEqual([st.disc, st.doc, st.tool]);
      expect(strip(shape(importWizardView(reg, t, 1)))).toEqual(W.importNewRev[key].vals);
    }
  });

  it('steps 1 → 3, back, another tool; closing resets to step 1', () => {
    const t = importTargetFor(reg, 'elec')!;
    for (const step of [1, 2, 3]) expect(strip(shape(importWizardView(reg, t, step)))).toEqual(W.steps[step]);
    expect(strip(shape(importWizardView(reg, t, 2)))).toEqual(W.back);
    expect(strip(shape(importWizardView(reg, { ...t, tool: 3 }, 1)))).toEqual(W.toolChoice);
    expect(W.closed).toMatchObject({ open: false, step: 1 });
    expect(IMPORT_ROWS).toBe(27);
  });

  it('URL targets: known discipline and deliverable, tool from the URL or the document', () => {
    expect(importTargetOf(reg, 'elec', 'lst-ins-026', undefined)).toEqual({ disc: 'elec', doc: 'LST-INS-026', tool: 0 });
    expect(importTargetOf(reg, 'elec', 'LST-INS-026', '2')).toEqual({ disc: 'elec', doc: 'LST-INS-026', tool: 2 });
    expect(importTargetOf(reg, 'elec', 'LST-INS-026', '9')).toEqual({ disc: 'elec', doc: 'LST-INS-026', tool: 0 });
    expect(importTargetOf(reg, 'auto', 'LST-IO-026', 'x')).toEqual({ disc: 'auto', doc: 'LST-IO-026', tool: 2 });
    expect([importTargetOf(reg, 'client', 'LST-INS-026', '0'), importTargetOf(reg, 'elec', 'BOD-CLI-026', '0'), importTargetOf(reg, 'elec', undefined, '0')]).toEqual([null, null, null]);
    // Its own deliverable is not an input of the discipline.
    expect([importTargetOf(reg, 'elec', 'SCH-ELE-026', '2'), importTargetOf(reg, 'process', 'LST-INS-026', '0')]).toEqual([null, null]);
  });
});
